import path from "node:path";
import {
    getLlama, Llama, LlamaChatSession, LlamaChatSessionPromptCompletionEngine, LlamaContext, LlamaContextSequence, LlamaEmbedding, LlamaEmbeddingContext, LlamaModel
} from "node-llama-cpp";
import {withLock, State} from "lifecycle-utils";
import {functions} from "./functions.ts"
import packageJson from "../../package.json";

const customSystemPrompt = "You are a helpful AI assistant named Claudia. You have access to some tools which you can use if you need to. If you do not know the answer even after using the tools, do not make up an answer. You may instead ask any clarifying questions"
export const llmState = new State<LlmState>({
    appVersion: packageJson.version,
    llama: {
        loaded: false
    },
    model: {
        loaded: false
    },
    context: {
        loaded: false
    },
    embeddingContext: {
        loaded: false
    },
    knowledgeBase: {
        ingested: false
    },
    contextSequence: {
        loaded: false
    },
    chatSession: {
        loaded: false,
        generatingResult: false,
        simplifiedChat: [],
        draftPrompt: {
            prompt: "",
            completion: ""
        }
    }
});

export type LlmState = {
    appVersion?: string,
    llama: {
        loaded: boolean,
        error?: string
    },
    selectedModelFilePath?: string,
    model: {
        loaded: boolean,
        loadProgress?: number,
        name?: string,
        error?: string
    },
    context: {
        loaded: boolean,
        error?: string
    },
    embeddingContext: {
        loaded: boolean,
        error?: string,

    },
    knowledgeBase: {
        ingested: boolean,
        pathName?: string,
        error?: string
    },
    contextSequence: {
        loaded: boolean,
        error?: string
    },
    chatSession: {
        loaded: boolean,
        generatingResult: boolean,
        simplifiedChat: SimplifiedChatItem[],
        draftPrompt: {
            prompt: string,
            completion: string
        }
    }
};

type SimplifiedChatItem = {
    type: "user" | "model",
    message: string
};

let llama: Llama | null = null;
let model: LlamaModel | null = null;
let context: LlamaContext | null = null;
let contextSequence: LlamaContextSequence | null = null;
let embeddingContext : LlamaEmbeddingContext | null = null;
let chatSession: LlamaChatSession | null = null;
let chatSessionCompletionEngine: LlamaChatSessionPromptCompletionEngine | null = null;
let promptAbortController: AbortController | null = null;
let inProgressResponse: string = "";

export const llmFunctions = {
    async loadLlama() {
        await withLock(llmFunctions, "llama", async () => {
            if (llama != null) {
                try {
                    await llama.dispose();
                    llama = null;
                } catch (err) {
                    console.error("Failed to dispose llama", err);
                }
            }

            try {
                llmState.state = {
                    ...llmState.state,
                    llama: {loaded: false}
                };

                llama = await getLlama();
                llmState.state = {
                    ...llmState.state,
                    llama: {loaded: true}
                };

                llama.onDispose.createListener(() => {
                    llmState.state = {
                        ...llmState.state,
                        llama: {loaded: false}
                    };
                });
            } catch (err) {
                console.error("Failed to load llama", err);
                llmState.state = {
                    ...llmState.state,
                    llama: {
                        loaded: false,
                        error: String(err)
                    }
                };
            }
        });
    },
    async loadModel(modelPath: string) {
        await withLock(llmFunctions, "model", async () => {
            if (llama == null)
                throw new Error("Llama not loaded");

            if (model != null) {
                try {
                    await model.dispose();
                    model = null;
                } catch (err) {
                    console.error("Failed to dispose model", err);
                }
            }

            try {
                llmState.state = {
                    ...llmState.state,
                    model: {
                        loaded: false,
                        loadProgress: 0
                    }
                };

                model = await llama.loadModel({
                    modelPath,
                    onLoadProgress(loadProgress: number) {
                        llmState.state = {
                            ...llmState.state,
                            model: {
                                ...llmState.state.model,
                                loadProgress
                            }
                        };
                    }
                });
                llmState.state = {
                    ...llmState.state,
                    model: {
                        loaded: true,
                        loadProgress: 1,
                        name: path.basename(modelPath)
                    }
                };

                model.onDispose.createListener(() => {
                    llmState.state = {
                        ...llmState.state,
                        model: {loaded: false}
                    };
                });
            } catch (err) {
                console.error("Failed to load model", err);
                llmState.state = {
                    ...llmState.state,
                    model: {
                        loaded: false,
                        error: String(err)
                    }
                };
            }
        });
    },
    async createContext() {
        await withLock(llmFunctions, "context", async () => {
            if (model == null)
                throw new Error("Model not loaded");

            if (context != null) {
                try {
                    await context.dispose();
                    context = null;
                } catch (err) {
                    console.error("Failed to dispose context", err);
                }
            }

            try {
                llmState.state = {
                    ...llmState.state,
                    context: {loaded: false}
                };

                context = await model.createContext();
                llmState.state = {
                    ...llmState.state,
                    context: {loaded: true}
                };

                context.onDispose.createListener(() => {
                    llmState.state = {
                        ...llmState.state,
                        context: {loaded: false}
                    };
                });
            } catch (err) {
                console.error("Failed to create context", err);
                llmState.state = {
                    ...llmState.state,
                    context: {
                        loaded: false,
                        error: String(err)
                    }
                };
            }
        });
    },
    async createContextSequence() {
        await withLock(llmFunctions, "contextSequence", async () => {
            if (context == null)
                throw new Error("Context not loaded");

            try {
                llmState.state = {
                    ...llmState.state,
                    contextSequence: {loaded: false}
                };

                contextSequence = context.getSequence();
                llmState.state = {
                    ...llmState.state,
                    contextSequence: {loaded: true}
                };

                contextSequence.onDispose.createListener(() => {
                    llmState.state = {
                        ...llmState.state,
                        contextSequence: {loaded: false}
                    };
                });
            } catch (err) {
                console.error("Failed to get context sequence", err);
                llmState.state = {
                    ...llmState.state,
                    contextSequence: {
                        loaded: false,
                        error: String(err)
                    }
                };
            }
        });
    },
    async createEmbeddingContext() {
        await withLock(llmFunctions, "embeddingContext", async () => {
            if (model == null)
                throw new Error("Model not loaded");

            if (embeddingContext != null) {
                try {
                    await embeddingContext.dispose();
                    embeddingContext = null;
                } catch (err) {
                    console.error("Failed to dispose context", err);
                }
            }

            try {
                llmState.state = {
                    ...llmState.state,
                    embeddingContext: {loaded: false}
                };

                embeddingContext = await model.createEmbeddingContext();
                llmState.state = {
                    ...llmState.state,
                    embeddingContext: {loaded: true}
                };

                embeddingContext.onDispose.createListener(() => {
                    llmState.state = {
                        ...llmState.state,
                        embeddingContext: {loaded: false}
                    };
                });
            } catch (err) {
                console.error("Failed to create embedding context", err);
                llmState.state = {
                    ...llmState.state,
                    embeddingContext: {
                        loaded: false,
                        error: String(err)
                    }
                };
            }
        });
    },
    chatSession: {
        async createChatSession() {
            await withLock(llmFunctions, "chatSession", async () => {
                if (contextSequence == null)
                    throw new Error("Context sequence not loaded");

                if (chatSession != null) {
                    try {
                        chatSession.dispose();
                        chatSession = null;
                        chatSessionCompletionEngine = null;
                    } catch (err) {
                        console.error("Failed to dispose chat session", err);
                    }
                }

                try {
                    llmState.state = {
                        ...llmState.state,
                        chatSession: {
                            loaded: false,
                            generatingResult: false,
                            simplifiedChat: [],
                            draftPrompt: llmState.state.chatSession.draftPrompt
                        }
                    };

                    llmFunctions.chatSession.resetChatHistory(false);

                    try {
                        await chatSession?.preloadPrompt("", {
                            signal: promptAbortController?.signal
                        });
                    } catch (err) {
                        // do nothing
                    }
                    chatSessionCompletionEngine?.complete(llmState.state.chatSession.draftPrompt.prompt);

                    llmState.state = {
                        ...llmState.state,
                        chatSession: {
                            ...llmState.state.chatSession,
                            loaded: true
                        }
                    };
                } catch (err) {
                    console.error("Failed to create chat session", err);
                    llmState.state = {
                        ...llmState.state,
                        chatSession: {
                            loaded: false,
                            generatingResult: false,
                            simplifiedChat: [],
                            draftPrompt: llmState.state.chatSession.draftPrompt
                        }
                    };
                }
            });
        },
        async prompt(message: string) {
            await withLock(llmFunctions, "chatSession", async () => {
                if (chatSession == null)
                    throw new Error("Chat session not loaded");

                llmState.state = {
                    ...llmState.state,
                    chatSession: {
                        ...llmState.state.chatSession,
                        generatingResult: true,
                        draftPrompt: {
                            prompt: "",
                            completion: ""
                        }
                    }
                };
                promptAbortController = new AbortController();

                llmState.state = {
                    ...llmState.state,
                    chatSession: {
                        ...llmState.state.chatSession,
                        simplifiedChat: getSimplifiedChatHistory(true, message)
                    }
                };
                await chatSession.prompt(message, {
                    signal: promptAbortController.signal,
                    stopOnAbortSignal: true,
                    functions: functions,
                    onTextChunk(chunk) {
                        inProgressResponse += chunk;

                        llmState.state = {
                            ...llmState.state,
                            chatSession: {
                                ...llmState.state.chatSession,
                                simplifiedChat: getSimplifiedChatHistory(true, message)
                            }
                        };
                    }
                });
                llmState.state = {
                    ...llmState.state,
                    chatSession: {
                        ...llmState.state.chatSession,
                        generatingResult: false,
                        simplifiedChat: getSimplifiedChatHistory(false),
                        draftPrompt: {
                            ...llmState.state.chatSession.draftPrompt,
                            completion: chatSessionCompletionEngine?.complete(llmState.state.chatSession.draftPrompt.prompt) ?? ""
                        }
                    }
                };
                inProgressResponse = "";
            });
        },
        stopActivePrompt() {
            promptAbortController?.abort();
        },
        resetChatHistory(markAsLoaded: boolean = true) {
            if (contextSequence == null)
                return;
            chatSession?.dispose();
            chatSession = new LlamaChatSession({
                contextSequence,
                systemPrompt: customSystemPrompt,
                autoDisposeSequence: false,

            });
            chatSessionCompletionEngine = chatSession.createPromptCompletionEngine({
                onGeneration(prompt, completion) {
                    if (llmState.state.chatSession.draftPrompt.prompt === prompt) {
                        llmState.state = {
                            ...llmState.state,
                            chatSession: {
                                ...llmState.state.chatSession,
                                draftPrompt: {
                                    prompt,
                                    completion
                                }
                            }
                        };
                    }
                }
            });

            llmState.state = {
                ...llmState.state,
                chatSession: {
                    loaded: markAsLoaded
                        ? true
                        : llmState.state.chatSession.loaded,
                    generatingResult: false,
                    simplifiedChat: [],
                    draftPrompt: {
                        prompt: llmState.state.chatSession.draftPrompt.prompt,
                        completion: chatSessionCompletionEngine.complete(llmState.state.chatSession.draftPrompt.prompt) ?? ""
                    }
                }
            };

            chatSession.onDispose.createListener(() => {
                llmState.state = {
                    ...llmState.state,
                    chatSession: {
                        loaded: false,
                        generatingResult: false,
                        simplifiedChat: [],
                        draftPrompt: llmState.state.chatSession.draftPrompt
                    }
                };
            });
        },
        setDraftPrompt(prompt: string) {
            if (chatSessionCompletionEngine == null)
                return;

            llmState.state = {
                ...llmState.state,
                chatSession: {
                    ...llmState.state.chatSession,
                    draftPrompt: {
                        prompt: prompt,
                        completion: chatSessionCompletionEngine.complete(prompt) ?? ""
                    }
                }
            };
        }
    },
    embeddingContext: {
        async embedDocuments(documents: readonly string[]) {
            await withLock(llmFunctions, "embeddingContext", async () => {
                if (embeddingContext == null)
                    throw new Error("Embedding context not created");

                const embeddings = new Map<string, LlamaEmbedding>();
                await Promise.all(
                    documents.map(async (document) => {
                        const embedding = await embeddingContext?.getEmbeddingFor(document);
                        if (embedding) {
                            embeddings.set(document, embedding);
                        }

                        console.debug(
                            `${embeddings.size}/${documents.length} documents embedded`
                        );
                    })
                );

                return embeddings;
            }
        )},  
    }
} as const;

function getSimplifiedChatHistory(generatingResult: boolean, currentPrompt?: string) {
    if (chatSession == null)
        return [];

    const chatHistory: SimplifiedChatItem[] = chatSession.getChatHistory()
        .flatMap((item): SimplifiedChatItem[] => {
            if (item.type === "system")
                return [];
            else if (item.type === "user")
                return [{type: "user", message: item.text}];
            else if (item.type === "model")
                return [{
                    type: "model",
                    message: item.response
                        .filter((value) => typeof value === "string")
                        .join("")
                }];

            void (item satisfies never); // ensure all item types are handled
            return [];
        });

    if (generatingResult && currentPrompt != null) {
        chatHistory.push({
            type: "user",
            message: currentPrompt
        });

        if (inProgressResponse.length > 0)
            chatHistory.push({
                type: "model",
                message: inProgressResponse
            });
    }

    return chatHistory;
}

# Local Electron App using Node-Llama-Cpp
This is a demo app that lets you run inference on large language model (LLM) running locally on your PC. It is an Electron app built using TypeScript and [`node-llama-cpp`](https://github.com/withcatai/node-llama-cpp) which is a package that provides node.js bindings for llama.cpp. `node-llama-cpp` has CUDA support for your NVIDIA GPUs and can leverage it automatically when detected for the best performance from your hardware. There is no need to manually configure anything.

## Getting started


### Prerequisites
- To use `node-llama-cpp`'s CUDA support with your NVIDIA GPU, make sure you have CUDA Toolkit 12.2 or higher installed on your machine.


### Installation 
Install the required packages:
```bash
npm install
```

Start the project:
```bash
npm start
```

This will start an electron app as shown below:

![Model Downloading](images/model-downloading.png)
You can download any GGUF model directly from HuggingFace any then load it into the app. 

> **Note:** In order to use the tools used in this demo namely the weather tool and Tavily Search tool, you need to create API keys and specify them as environment variables. All environment variables should be prefixed with `VITE_`.<br>
Create a file in the root directory called `.env` with the following contents:<br>
```
VITE_ACCUWEATHER_API_KEY=your-accuweather-api-key-here
VITE_TAVILY_API_KEY=your-tavily-api-key-here
```


### Function Calling Support

In this app, we demonstrate how to provide a list of functions that a model can call during generation to retrieve information or perform actions.

Some models like Llama 3.1 that have built-in support for function calling. To use tool-calling with such models, you can simply add functions to `electron/state/functions.ts`.

As an example, we added a weather tool as shown below:
```typescript
getCurrentWeather: defineChatSessionFunction({
        description: "Get the current weather in a location",
        params: {
            type: "object",
            properties: {
                name: {
                    type: "string"
                },
            }
        },
        async handler(params) {
            try {
                const locationKey = await getLocationKey(params.name.toLowerCase());
                if (!locationKey) {
                    return `Could not find location key for "${location}".`;
                }

                const response = await axios.get(`${CURRENT_CONDITIONS_URL}/${locationKey}`, {
                    params: {
                        apikey: ACCUWEATHER_API_KEY
                    }
                });

                const weatherData = response.data[0];

                // Extract relevant weather information
                const weather: WeatherResponse = {
                    location: params.name.toLowerCase(),
                    temperature: weatherData.Temperature.Metric.Value,
                    description: weatherData.WeatherText,
                };

                return weather;
            } catch (error) {
                console.error('Error fetching weather data:', error);
                return `Could not retrieve weather for "${location}". Please try again.`;
            }
        }
    })
```
This allows us to ask the chatbot questions about the weather:

![Weather tool](images/tool-calling.png)

We also added support for asking questions about current events using the Tavily Search API as shown below:

![Weather tool](images/add-search-tools.png)

### Customization

You can customize the system prompt and personalize your chatbot by changing the `customSystemPrompt` in `electron/state/llmState.ts`. 

For example, you can add a system prompt like the following:
```
"You are an AI assistant named Sleepy Joe. You are lazy and don't like being asked questions so you answer very reluctantly. "
```
